\subsection{Topology and Propagation Models}
Consider an Orthogonal Frequency-Division Multiple Access (OFDMA) network with a single base station (BS) covering a circular area with radius $r$, $N_{e}$ eMBB users with indexes $\mathcal{N}_e \in \{1,\ldots, N_e\}$, $N_{U}$ URLLC users with indexes $ \mathcal{N}_U \in \{ N_e+1,\ldots, N_e + N_{U}\}$, and $N_{M}$ MBBLL users with indexes $\mathcal{N}_M \in \{ N_e + N_{U}+1,\ldots, N_e + N_{U} + N_{M}\}$, as shown in Fig.~\ref{fig:sys_mod}. 
% All users are randomly distributed over the entire BS coverage. 
As illustrated in Fig.~\ref{fig:sys_mod}(a), the hybrid 5G/6G oriented downlink transmission cell system serves users under a multiplexing scenario with co-existing eMBB, URLLC, MBBLL services. Also, each service is characterized by the number of users $\mathcal{N}_i$, service intensity $\lambda_i$, and latency requirement $d_i$, where $i \in \{e, U, M\}$. The base station transmits data in the downlink according to time-frequency resource grid $(t, f) \in \mathcal{T} \times \mathcal{F}$, which follows a frame and super-frame-based dual-timescale structure as shown in Fig.~\ref{fig:sys_mod}(b) \cite{zhang_joint_2018, tang_service_2019, yang_how_2021}. A sum of $\Bar{K}$ frames are contained in a super-frame. At the start of super-frame $l$, $l \in \{1, \ldots, L\}$, the resource grid is sliced according to some specific network slicing strategy. At the start of frame $k$, $k \in \{1, \ldots, \Bar{K}\}$, the legacy eMBB and URLLC (illustrated with blue color) and 6G MBBLL (illustrated with red color) services are allocated to resource grids $(t, f) \in \mathcal{T}_k \times \mathcal{F}$.

For any given time slot $t$ and sub-channel $f$, the equivalent transmission capacity for the $n^{\mathrm{th}}$ user is given by,
\begin{eqnarray} \label{eqn:capa}
r_n(t,f) =  B \log_2 \left(1 + b_n(t,f) |h_n(t,f)|^2  p(t,f)\right),
\end{eqnarray}
where $B$ denotes the sub-channel bandwidth, $h_n(t,f)$ denotes the normalized complex-valued channel fading coefficient\footnote{In this paper, we normalize the channel coefficient with respect to the noise power for illustration purposes.} between the BS and the $n^{\mathrm{th}}$ user, and $b_n(t,f) \in\{0,1\}$ denotes the indicator function, which equals to $1$ if the time-frequency element $(t,f)$ is allocated to the $n^{\mathrm{th}}$ user and zero otherwise. Since each time-frequency element can only be allocated executively to one user within a time frame $\mathcal{T}_k \times \mathcal{F}$, we have
\begin{eqnarray}
\label{constraint sub-channel}
% \begin{aligned}
\sum_{n \in \mathcal{N}_e \cup \mathcal{N}_U \cup \mathcal{N}_M}b_n(t,f) \leq 1, &&\forall(t,f) \in \mathcal{T}_k \times \mathcal{F}.
% \end{aligned}
\end{eqnarray}
Besides, $p(t,f)$ denotes the allocated transmission power for each time-frequency element $(t,f)$, which satisfies
\begin{eqnarray}
\label{constraint power}
\sum_{f \in \mathcal{F}} 
% \sum_{n \in \mathcal{N}} b_n(t, f) 
p(t,f) \leq P_{\mathrm{tot}}.
\end{eqnarray}  
In the above formulation, for time frame  $k$ with index $\mathcal{T}_k$ and bandwidth $\mathcal{F}$, the transmission throughput of the $n^{\mathrm{th}}$ user, $r_n(k)$, is thus given by
\begin{eqnarray}
r_n(k) = \sum_{(t,f) \in \mathcal{T}_k \times \mathcal{F}} r_n(t,f).
\label{frame_capa}\end{eqnarray}

\subsection{Traffic Models}
Denote $Q_n(k)$ to be the queue status of the $k^{\mathrm{th}}$ time frame for the $n^{\mathrm{th}}$ user. Then, the queuing dynamic is 
\begin{eqnarray}
\label{dynamic queue model}
    Q_{n}(k+1) = \max\{Q_{n}(k) - \eta r_n(k),0\} + \Lambda_n(k),
\end{eqnarray}
where $\eta = \frac{K_f}{L_{\mathrm{packet}}}$ denotes the normalized parameter corresponding to frame duration $K_f$ and packet length $L_{\mathrm{packet}}$, $\Lambda_n(k)$ is the number of arrived packets during the $k^{\mathrm{th}}$ time frame with 
\begin{eqnarray}
\mathbb{E}[\Lambda_n(k)] = 
\left\{
\begin{array}{l l}
  \lambda_e, & n \in \mathcal{N}_e,\\
  \lambda_U, & n \in \mathcal{N}_U, \\
  \lambda_M, & n \in \mathcal{N}_M,
\end{array}
\right.
\label{arrival}
\end{eqnarray}
where $\mathbb{E}(\cdot)$ denotes the mathematical expectation and $\lambda_e, \lambda_U, \lambda_M$ denote the average arrival rates for eMBB, URLLC, and MBBLL users, respectively. Once we denote $K = L \times \Bar{K}$ to be the total number of time frames, the average queuing backlogs for eMBB, URLLC, MBBLL UEs are given by, 
\begin{eqnarray}
\label{constraint average queue length}
\begin{aligned}
    &\limsup_{K\to\infty}\frac{1}{K}\sum_{k=0}^{K-1}Q_{n}(k)\leq 
    \left\{
    \begin{array}{l l}
      \delta_e, & n \in \mathcal{N}_e,\\
      \delta_U, & n \in \mathcal{N}_U, \\
      \delta_M, & n \in \mathcal{N}_M,
    \end{array} \right.
\end{aligned}
\end{eqnarray}
where $\delta_e = \lambda_e d_e$, $\delta_U = \lambda_U d_U$, and $\delta_M = \lambda_M d_M$ denote the delay requirements for eMBB, URLLC, and MBBLL users, respectively, as governed by the celebrating Little's law in the area of queuing theory \cite{little_littles_2008}. On the other hand, according to the 3GPP TR 38.913 \cite{noauthor_study_2022}, the URLLC packets should be delivered within a frame duration to satisfy the stringent delay requirement such that the above constraint \eqref{constraint average queue length} becomes
\begin{eqnarray}
% &Pr\left(r_n(k) \geq Q_n(k)\right) \geq 1 - \epsilon, n \in \mathcal{N}_U, \label{constraint URLLC rate} \\
&\eta r_n(k) \geq Q_n(k), n \in \mathcal{N}_U, \label{constraint URLLC rate} \\
&\underset{K\to\infty}{\limsup}\frac{1}{K}\displaystyle\sum_{k=0}^{K-1}Q_{n}(k)\leq 
\left\{
\begin{array}{l l}
  \delta_e, & n \in \mathcal{N}_e,\\
  % \delta_U, & n \in \mathcal{N}_U, \\
  \delta_M, & n \in \mathcal{N}_M.
\end{array} \right. \label{constraint average queue length, no URLLC}
\end{eqnarray}

{\color{black}
Furthermore, to isolate the legacy 5G eMBB and URLLC with the 6G MBBLL services, a frequency domain network slicing strategy has been adopted with the time-varying partition $\mathcal{F}_l$ and $\overline{\mathcal{F}_l}$\footnote{{\color{black}This isolation strategy aligns with 3GPP’s network slicing principles \cite{3GPP_38_401, 3GPP_28_530}, while addresses multi-generation coexistence challenges and provides QoS guarantees.}}, such that for the $l^{\mathrm{th}}$ super-frame, we have
}
\begin{eqnarray}
b_n(t,f) = 0, && \forall n \in \mathcal{N}_e \cup \mathcal{N}_U \  \& \ f \in \overline{\mathcal{F}_l}, \label{eqn:f_l_legacy}\\
b_n(t,f) = 0, && \forall n \in \mathcal{N}_M \ \& \ f \in \mathcal{F}_l, \label{eqn:f_l_6g}\\
\mathcal{F}_l \cup \overline{\mathcal{F}_l} = \mathcal{F}. \label{eqn:f_l}
\end{eqnarray}

The following assumptions are adopted through the rest of this paper. 
First, we consider the standard log-normal shadowing, where the magnitude of channel coefficients, i.e., $|h_n(t,f)|$, follows the super-frame based log-normal distribution with mean $\mu_{n}(l)$ and variance $\sigma^2_{n}$, where $\mu_{n}(l)$ stand for the pathloss component. 
Second, the temporal evolution of the pathloss component follows an autoregression model as given by \cite{baddour_autoregressive_2005, chopra_adaptive_2024}, 

\begin{small}
\begin{eqnarray}
    \begin{bmatrix}
        \mu_{1}(l)\\
        \ldots\\
        \mu_{N}(l)
    \end{bmatrix} 
    = \bm{A}(l - 1)
    \begin{bmatrix}
       \mu_{1}(l-1)\\
        \ldots\\
       \mu_{N}(l-1)
    \end{bmatrix} + \bm{N}_{\mu}, \quad l \geq 1. 
\label{pathloss_ar}
\end{eqnarray}
\end{small}

\noindent In the above expression, $\bm{A}(l) = \textrm{diag}[a_1(l), \ldots, a_{N}(l)]$ denotes the temporal correlation of the $l^{th}$ super-frame that evolves according to $\bm{A}(l) = \beta \bm{A}(l - 1) + \bm{N}_{\bm{A}}$, where $\textrm{diag}(\bm{a})$ denotes the diagonal matrix composed with vector $\bm{a}$, and $\beta$ is any positive constant that satisfies $0 \leq \beta < 1$ which stands for the damping term of classical autoregression model as specified in \cite{hamilton_time_1994}. 
Third, complex-valued channel coefficients $h_n(t, f)$ are sensed in each allocation frame. 
Fourth, $\bm{N}_{\mu}$ and $\bm{N}_{\bm{A}}$ follow the standard zero mean Gaussian distributions with covariance matrices $\bm{Q}_{\mu}$ and $\bm{Q}_{\bm{A}}$, respectively. 
Fifth, $\Lambda_n(k)$ follows Poisson distribution \cite{karagiannis_nonstationary_2004} with mean arrival rate $\lambda_n$. 
Last but not least, once we assume the minimum ergodic period of both $\{|h_n(t, f)|\}$ and $\{\lambda_n(k)\}$ as $K_e$, as specified in \cite{tang_service_2019, yang_how_2021}, we have $\Bar{K} > K_e$, and $\Bar{K}$ is sufficiently large such that $\{|h_n(t, f)|\}$ within each super-frame is independent and identically distributed (i.i.d.) and ergodic, which results from the significant difference in the timescales. 
% Last but not least,  $\Lambda_n(k)$ follows Poisson distribution \cite{karagiannis_nonstationary_2004} with mean arrival rate $\lambda_n$. 

\section{Problem Formulation and Transformation}\label{problem formulation}
% \subsection{Optimization Problem with Ideal Model}
In this section, we first formulate the average throughput maximization problem exploiting a general optimization framework and than discuss the Lyapunov drift-based formulation. 

To start with, based on the per-user throughput expression as given in \eqref{frame_capa}, we can calculate the total throughput of BS by accumulating over all the possible users, e.g., $n \in \mathcal{N}_e \cup \mathcal{N}_U \cup \mathcal{N}_M$. By averaging over the total number of time frames, $K$, the original throughput maximization problem can be formulated as follows. 
%\subsection{Problem Formulation}
\begin{Prob}[Original Problem] The average throughput of the unified QoS-aware multiplexing framework can be maximized via the following optimization problem.
\begin{eqnarray}\label{prob_original}
    \underset{\{b_n(t,f)\}, \{p(t,f)\}, \{\mathcal{F}_l\}}{\textrm{maximize}} && \lim_{K \to \infty}\frac{1}{K}\sum_{k = 1}^{K}\sum_{n \in \mathcal{N}_e \cup \mathcal{N}_U \cup \mathcal{N}_M} r_n(k), \nonumber \\
    \textrm{subject to} \qquad
    && \eqref{constraint sub-channel}, \eqref{constraint power}, \eqref{constraint URLLC rate}-\eqref{eqn:f_l}, \nonumber
\end{eqnarray}
where the frequency domain network slicing strategy $\{\mathcal{F}_l\}$ is updated on a super-frame basis and other resources, e.g., $\{b_n(t,f)\}, \{p(t,f)\}$, are determined on a per time frame basis.
\label{prob URLLC}
\end{Prob}

By mixing the discrete network slicing strategy $\{\mathcal{F}_l\}$, the discrete bandwidth allocation $\{b_n(t, f)\}$, and the continuous power allocation $\{p(t, f)\}$, the above problem belongs to a NP-hard mixed integer non-linear programming (MINLP) problem as specified in \cite{boukouvala_global_2016}. In addition, with the long-term average queuing constraint \eqref{constraint average queue length, no URLLC} and coupled queuing dynamics due to shared wireless resources, Problem~\ref{prob URLLC} becomes even more challenging to solve in general. 

% Strong rate stability over the super-frame $l$, which is a prerequisite for \eqref{segment_cons}, is guaranteed by:
% \begin{align}\label{strong_stability}
%     \mathbb{E}\left[\frac{1}{\Bar{K}}\sum_{k = l \times \Bar{K} + 1}^{(l + 1) \times \Bar{K}} r_n(k) \right] \geq \mathbb{E}\left[\frac{1}{\Bar{K}}\sum_{k = l \times \Bar{K} + 1}^{(l + 1) \times \Bar{K}} \Lambda_n(k)\right]. 
% \end{align}
% In addition, 
To make it mathematically tractable, 
we denote a virtual queue defined as $\Gamma(k)\triangleq[G_1(k), G_2(k), \ldots, G_n(k)]$ with dynamics $G_n(k + 1) = \max\{G_n(k) + Q_n(k + 1) - \delta_{e,M}, 0\}, n \in \mathcal{N}_e \cup \mathcal{N}_M$, and the corresponding weighted-Lyapunov function \cite{neely_mj_stochastic_2010} is given by,\begin{eqnarray}
    L(\Gamma(k))\triangleq\frac{\omega_{Q}}{2}\sum_{n \in \mathcal{N}_e \cup \mathcal{N}_M}{G_n(k)}^2,
\end{eqnarray}
where $\omega_{Q}>0$ is a weight factor for the virtual queue. By utilizing the Lyapunov drift theorem \cite{neely_mj_stochastic_2010}, we can solve Problem~\ref{prob URLLC} through minimizing the drift-minus-utility (DMU) function as summarized in the following lemma.

\begin{Lem}[Lyapunov Drift \cite{neely_mj_stochastic_2010}] \label{lem_dmu_long_term}
If we denote the DMU function to be $\Delta(\Gamma(k)) - \omega_{T} \mathbb{E}\left[\sum_{n \in \mathcal{N}_e \cup \mathcal{N}_U \cup \mathcal{N}_M} r_n(k)|\Gamma(k)\right]$, then the objective function in Problem~\ref{prob URLLC} can be maximized when the following upper bound of DMU function is minimized.

\begin{small}
\vspace{-6mm}
    \begin{align} \label{DMU upper bound}
        \Delta(\Gamma(k)) - \omega_{T}\mathbb{E}\left[ \sum_{n \in \mathcal{N}_e \cup \mathcal{N}_U \cup \mathcal{N}_M} r_n(k)|\Gamma(k) \right] \nonumber \\
        \leq \mathbb{E} \left[ \frac{\omega_{Q}}{2} \sum_{n \in \mathcal{N}_e \cup \mathcal{N}_M}\big(C_n(k) - 2G_n(k) \eta r_n(k)\big)|\Gamma(k)\right]\nonumber\\
        - \omega_{T}\mathbb{E}\left[ \sum_{n \in \mathcal{N}_e \cup \mathcal{N}_U \cup \mathcal{N}_M} r_n(k)|\Gamma(k) \right], \qquad \qquad \qquad \quad
    \end{align}
\end{small}

\noindent where $\Delta(\Gamma(k)) \triangleq \mathbb{E}\left[L(\Gamma(k + 1)) - L(\Gamma(k))|\Gamma(k)\right]$, $\omega_{T}>0$ denotes the weight factor for total throughput, and $C_n(k) = {(Q_n(k) + \Lambda_n(k))}^2 + {\delta_{e,M}}^2 + 2 G_n(k) Q_n(k) + 2 G_n(k) \Lambda_n(k)$ denotes the throughput irrelevant terms.
\end{Lem}
\begin{proof}
Please refer to Appendix~\ref{appendix:lem_1} for the proof.
\end{proof}
% \begin{Cor}
% After merging, the objective function of our Lyapunov optimization problem becomes
% \begin{eqnarray}
% \sum_{n\in\mathcal{N}_e \cup \mathcal{N}_M} (\omega_Q G_n(k) + \omega_T) r_n(k). 
% \label{max_DMU}
% \end{eqnarray}
% The original problem~\eqref{prob_original} becomes a weighted sum rate optimization problem. In this case, when the weight of the queue stability $\omega_Q$ dominates, the system will prioritize optimizing the rate of users with larger virtual queue backlogs. When the weight of the sum throughput $\omega_T$ dominates, the system will maximize the rate of each user fairly. 
% \end{Cor}
By applying Lemma~\ref{lem_dmu_long_term}, the original average throughput maximization problem can be equivalently transformed to the following drift-based formulation. 
\begin{Prob}[Drift-based Formulation] The upper bound of the DMU function can be optimized via the following optimization framework:

\begin{small}
       \begin{align}
        \underset{\{\mathcal{F}_l\}}{\textrm{max}} \quad & \lim_{L \to \infty} \frac{1}{L} \sum_{l = 1}^{L} \left\{\frac{1}{\Bar{K}}\sum_{k = (l - 1) \times \Bar{K} + 1}^{l \times \Bar{K}} F^*_k(\mathcal{F}_l)\right\}, \nonumber\\
        \textrm{s.t.} \quad & F^*_k(\mathcal{F}_l) \triangleq \begin{cases}
            \underset{\{b_n(t, f)\}, \atop \{p(t, f)\}}{\textrm{max}}& \displaystyle\sum_{n \in \mathcal{N}_e \cup \mathcal{N}_M} \omega_Q G_n(k) r_n(k) \nonumber\\
            & - \displaystyle\sum_{n \in \mathcal{N}_e \cup \mathcal{N}_M} \frac{\omega_Q}{2} C_n(k)\nonumber\\
            & + \displaystyle\sum_{n \in \mathcal{N}_e \cup \mathcal{N}_U \cup \mathcal{N}_M} \omega_T r_n(k), \nonumber\\
            \quad \textrm{s.t.} &
            \eqref{constraint sub-channel}, \eqref{constraint power}, \eqref{constraint URLLC rate}, \eqref{eqn:f_l_legacy}-\eqref{eqn:f_l}. \nonumber\\
            \end{cases} \\
        % & \eqref{pathloss_ar}
        % , \eqref{strong_stability}
        \nonumber
    \vspace{-6mm}
    \end{align} 
\end{small}
\label{prob Lyapunov}
% \vspace{}
\vspace{-6mm}
\end{Prob}
\noindent With the above transformation, we can effectively decouple the queueing dynamics into dual-timescale hierarchical optimization structure, where the inner optimization focuses on solving the short term power and bandwidth allocation within each time frame and the outer one solves the optimal network slicing strategy based on the obtained utility $F^*_k(\mathcal{F}_l)$.

\section{Dual-timescale Resource Allocation Under Stationary Case}\label{sta}

In this section, we focus on solving the drift-based Problem~\ref{prob Lyapunov} under the stationary condition, e.g., $\bm{A}(l) = \bm{I}, \bm{N}_{\bm{A}} = \bm{N}_{\mu} = \bm{0}$, and constraint \eqref{pathloss_ar} is degenerated into the following expression,  
\begin{align}
        [\mu_{1}(l) \ldots \mu_{N}(l)]^{T} = [\mu_{1}(l-1) \ldots \mu_{N}(l-1)]^{T}, l \geq 1. \label{stationary assumption}
\end{align}
With the dual-timescale hierarchical optimization framework as described in Problem~\ref{prob Lyapunov}, we decompose it into a frame-scale resource allocation problem for the fixed network slicing strategy $\mathcal{F}_l$, and then solve the optimal network slicing strategy in the super-frame scale as follows.
\begin{Prob} The optimal resource allocation strategy can be obtained by iteratively solving the following two subproblems.
\begin{subproblem}[Frame-Scale Resource Allocation]
    By dropping those irrelevant terms from $F_k^*(\mathcal{F}_l)$ such as $C_n(k)$, the frame scale resource allocation problem under any given $\mathcal{F}_l$ is equivalent to, 

    \begin{small}
    \vspace{-3mm}
    \begin{eqnarray}
         \underset{\{b_n(t, f)\}, \{p(t, f)\}}{\textrm{maximize}} && \displaystyle\sum_{n\in\mathcal{N}_e \cup \mathcal{N}_M} \omega_Q G_n(k) \eta r_n(k) \nonumber\\
         && + \sum_{n \in \mathcal{N}_e \cup \mathcal{N}_U \cup \mathcal{N}_M}\omega_T r_n(k)\label{inner_opt}\\
         \textrm{subject to} && \eqref{constraint sub-channel}, \eqref{constraint power}, \eqref{constraint URLLC rate}, \eqref{eqn:f_l_legacy}-\eqref{eqn:f_l}.  \nonumber
         \vspace{-6mm}
    \end{eqnarray} \label{prob frame}
    \end{small}

    \noindent Note that solving the frame-scale resource allocation problem is still challenging due to its MINLP and coupled nature for $\{b_n(t, f)\}$ and $\{p(t, f)\}$. 
\end{subproblem}

\begin{subproblem}[Super-frame Scale Network Slicing] With the obtained utility $F^*_k(\mathcal{F}_l)$,  the super-frame scale network slicing problem to maximize the overall utility is given by

\begin{small}
\vspace{-3mm}
\begin{eqnarray}
    \underset{\{\mathcal{F}_l\}}{\textrm{maximize}} && \lim_{L \to \infty} \frac{1}{L} \sum_{l = 1}^{L}\left\{\frac{1}{\Bar{K}}\sum_{k = (l - 1) \times \Bar{K} + 1}^{l \times \Bar{K}}  F^*_k(\mathcal{F}_l) \right\}. \label{obj_hierarchical stochastic problem}
    % \\
    % \textrm{subject to} && \eqref{stationary assumption}. \nonumber
\end{eqnarray}
\end{small}

The super-frame scale network slicing problem is also challenging as the objective function is non-convex and temporal correlated. 
To solve this, several methods have been proposed. 
Indeed, when a closed-form $F_k^*(\mathcal{F}_l)$ is available, the problem can be handled via standard dynamic programming methods \cite{r_bellman_dynamic_1966}. 
On the other hand, by introducing stochastic characteristic into $F_k^*(\mathcal{F}_l)$, efficient upper confidence bound (UCB)-based exploration schemes are proved to achieve asymptotical optimality under certain sub-Gaussian stochastic distributions \cite{zanzi_laco_2021}. 
{\color{black}
However, $F_k^*(\mathcal{F}_l)$ in the considered setting is a non-stochastic \cite{auer_nonstochastic_2002} objective function given under both the backlog status and the frame scale resource allocation policies, thus aforementioned methods may fail to exhibit optimal behavior. 
}


\label{hierarchical stochastic problem}
\end{subproblem}
\end{Prob}

