\subsection{Super-frame Scale Network Slicing}\label{subsec:saa admm}
With the obtained utility for given $\mathcal{F}_l$ through Algorithm~\ref{alg_psum_bcd}, e.g., $F^*_k(\mathcal{F}_l)$, we focus on solving the long-term utility maximization problem across different network slicing strategies $\{\mathcal{F}_l\}$. To address Problem~\ref{hierarchical stochastic problem}, we apply non-stochastic contextual bandit based methods\cite{neu_efficient_2020}, where the virtual and buffer queue statuses, e.g., $\{G_n((l - 1)\times\Bar{K}), Q_n((l - 1)\times\Bar{K})\}$, are chosen to be contextual features. Since the closed-form expression for $F^*_k(\mathcal{F}_l)$ is unavailable, we directly propose a network slicing algorithm as follows, namely Ad2S algorithm, and discuss the asymptotical optimality properties in Section~\ref{performance analysis}. 

\begin{algorithm}
        \caption{Proposed Algorithm for Problem~\ref{hierarchical stochastic problem}}
    \label{stationary_alg}
    \begin{algorithmic}[1]
    \STATE Initialization: Initialize learning rate, exploration parameter, and per-subcarrier loss, e.g., $\eta = L^{-\frac{2}{3}}(|\mathcal{F}|(1 + 4N))^{-\frac{1}{3}}(\log |\mathcal{F}|)^{\frac{2}{3}}$,$\gamma = L^{-\frac{1}{3}}(|\mathcal{F}|(1 + 4N)\log |\mathcal{F}|)^{\frac{1}{3}}$, $G_n(0) = Q_n(0) = 1, \forall n \in [1,N]$, $\pi_0(f|\bm{X}_l) = \frac{1}{|\mathcal{F}|}, \hat{\bm{\theta}}_{0, f} = \bm{0} \in \mathbb{R}^{1 + 4N}, \forall f \in [1, \ldots, |\mathcal{F}|]$;
    \FOR{$l = 1, \ldots, L$}
        \STATE \label{step start} 
        Based on the observed queue statuses, generate $\bm{X}_l$ according to $[1, G_1((l - 1)\times\Bar{K}), Q_1((l - 1)\times\Bar{K}), Q_1^2((l - 1)\times\Bar{K}), G_1((l - 1)\times\Bar{K})Q_1((l - 1)\times\Bar{K}), \ldots, G_N((l - 1)\times\Bar{K})Q_N((l - 1)\times\Bar{K})]$.
        \STATE \label{step policy generation} Draw $\mathcal{F}_l$\footnotemark  ~from the policy defined as
        \begin{small}
        \begin{align}
            \pi_l(f|\bm{X}_l) = (1 - \gamma) \frac{\exp\left( \eta \displaystyle\sum_{l' = 0}^{l - 1}\langle \bm{X}_l, \hat{\bm{\theta}}_{l', f} \rangle \right)}{\displaystyle\sum_{f' \neq f} \exp\left( \eta \displaystyle\sum_{l' = 0}^{l - 1}\langle \bm{X}_l, \hat{\bm{\theta}}_{l', f'} \rangle \right)} + \frac{\gamma}{|\mathcal{F}|}, 
        \end{align}
        \end{small}
        where $\langle \cdot, \cdot \rangle$ stands for the inner product in the Euclidean space as specified in \cite{anton_elementary_1987}, $\hat{\theta}_{l, f}$ is the estimated linear loss vector for choosing $f$ as the slicing decision $\mathcal{F}_l$; 
        % \STATE Choose $\mathcal{F}_l \sim \pi_l(f|\bm{X}_l)$; 
        \FOR{$k \in [(l - 1)\times\Bar{K} + 1, l \times \Bar{K}]$}
            \STATE Run Algorithm \ref{alg_psum_bcd} and acquire $F^*_k(\mathcal{F}_l)$;
        \ENDFOR
        \STATE \label{step end} Update $\hat{\bm{\theta}}_{l, f}$ according to
        \begin{small}
        \begin{align}
            \hat{\bm{\theta}}_{l, f} = \frac{\mathbb{I}_{\{ \mathcal{F}_l = f \}}}{\pi_l(f|\bm{X}_l)}   \frac{\frac{1}{\Bar{K}}\displaystyle\sum_{k = (l - 1) \times \Bar{K} + 1}^{l \times \Bar{K}}  F^*_k(\mathcal{F}_l)}{{\bm{X}_l}^T {\bm{X}_l}} \bm{X}_l, 
        \end{align}    
        \end{small}
        where $\mathbb{I}_{\{\cdot\}}$ stands for the indicator function. 
    \ENDFOR
    \end{algorithmic}
\end{algorithm}
\footnotetext{Noting that flat fading is widely adopted in sufficient number of orthogonal slicing works such as \cite{kwak_dynamic_2017, tang_service_2019, yang_how_2021}, therefore we focus on deriving the adequate quantity of sub-channels (i.e., $|\mathcal{F}_l|$) allocated to each slices. }
