\subsection{Network Slicing Refinement with Predictive Results}
With the obtained $\hat{\bm{\mu}}(l)$, we focus on tailoring Algorithm~\ref{stationary_alg} into adaptation to non-stationary channel statistics. To be specific, to eliminate the non-stationary throughput variation over super-frames, we adopt the following refinements to Alg.~\ref{stationary_alg}, and name it after adaptive adversarial slicing-non-stationary refinement (Ad2S-NR) algorithm. 
\begin{itemize}
    \item First, at the start of each super-frame, i.e., ahead of step \ref{step start}, run ME-KF and obtain $\hat{\bm{\mu}}(l)$. 

    \item Second, we redefine the contextual vector $\bm{X}(l) = [1, G_1((l - 1)\times\Bar{K}), Q_1((l - 1)\times\Bar{K}), Q_1^2((l - 1)\times\Bar{K}), G_1((l - 1)\times\Bar{K})Q_1((l - 1)\times\Bar{K}), \hat{R}_1(l), \hat{R}_1^2(l),  Q_1((l - 1)\times\Bar{K}) \hat{R}_1(l),  G_1((l - 1)\times\Bar{K}) \hat{R}_1(l), \ldots, G_N((l - 1)\times\Bar{K}) \hat{R}_N(l)]$, where 
    \begin{small}
    \begin{align}
        \hat{R}_n(l) = \left\{\begin{array}{ll}
            2 \hat{\mu}_n(l) \cdot \log_2(e), & \hat{\mu}_n(l) \geq \frac{\ln\left( \frac{\tau |\mathcal{F}|}{P_{\mathrm{tot}}} \right)}{2}, \\
            e^{-\bm{P}_{N+n, N+n}(l)} \cdot e^{2\hat{\mu}_n(l)} & \hat{\mu}_n(l) < \frac{\ln\left( \frac{\tau |\mathcal{F}|}{P_{\mathrm{tot}}} \right)}{2}, 
        \end{array}\right.
    \label{throughput_approximate}
    \end{align} 
    % \vspace{-3mm}
    \end{small}
    is the approximated unit spectral efficiency level related with $\hat{\mu}_n(l)$, $\tau$ denotes the threshold.
    \item Third, we resize the per-subcarrier loss as $\hat{\bm{\theta}}_{l, f} \in \mathbb{R}^{1 + 8N}, \forall f \in [1, \ldots, |\mathcal{F}|]$. 
\end{itemize}


\section{Performance Analysis}\label{performance analysis}
{\color{black}
    In this section, we analyze the asymptotical optimality and computational complexity properties with both Ad2S and Ad2S-NR. 
}
% In this section, we analyze the asymptotical optimality properties with both Ad2S and Ad2S-NR. 
\begin{Thm}[Asymptotical Optimality for Ad2S and Ad2S-NR]
    By setting learning rate and exploration parameter as $\eta = L^{-\frac{2}{3}}(|\mathcal{F}|(1 + 4N))^{-\frac{1}{3}}(\log (|\mathcal{F}|))^{\frac{2}{3}}$ and $\gamma = L^{-\frac{1}{3}}(|\mathcal{F}|(1 + 4N)\log (|\mathcal{F}|))^{\frac{1}{3}}$, respectively, for Ad2S, the asymptotic optimality in terms of cumulative regret\footnote{The cumulative regret represents the gap between the historical slicing choices and the optimal slicing choice. As \( l \to \infty \), if the regret grows sublinearly, the system tends toward asymptotic optimality \cite{prabhu_sequential_2022}. } is bounded as follows, 
    \begin{align}
        \mathrm{Regret}{L}^{\textrm{Ad2S}} \leq 5L^{\frac{2}{3}}(|\mathcal{F}|(1 + 4N)\log|\mathcal{F}|)^{\frac{1}{3}} F_{\mathrm{max}}. \label{sta_regret}
    \end{align}
    where $F_{\mathrm{max}}$ is a constant that satisfies $F_{\mathrm{max}} \geq \frac{1}{\Bar{K}}\sum_{k = (l - 1) \times \Bar{K} + 1}^{l \times \Bar{K}}F^*_k(\mathcal{F}_l), \forall l$. 

    While under non-stationary cases which $\bm{\mu}(l)$ evolves as \eqref{pathloss_ar}, by setting learning rate and exploration parameter as $\eta = L^{-\frac{2}{3}}(|\mathcal{F}|(1 + 8N))^{-\frac{1}{3}}(\log |\mathcal{F}|)^{\frac{2}{3}}$ and $\gamma = L^{-\frac{1}{3}}(|\mathcal{F}|(1 + 8N)\log |\mathcal{F}|)^{\frac{1}{3}}$, respectively, for Ad2S-NR, the asymptotic optimality in terms of cumulative regret is bounded as follows, 
    \begin{align}\label{non_sta_regret}
        \mathrm{Regret}_{L}^{\textrm{Ad2S-NR}} \leq & 5L^{\frac{2}{3}}(|\mathcal{F}|(1 + 8N)\log|\mathcal{F}|)^{\frac{1}{3}} F_{\mathrm{max}}. 
        % \\
        % & + 2 \epsilon \sqrt{(1 + 8N)} L. \nonumber
    \end{align}
    where both $\mathrm{Regret}_{L}^{\textrm{Ad2S}}$ and $\mathrm{Regret}{L}^{\textrm{Ad2S-NR}}$ are denoted as 
    \begin{align}\label{regret}
        \mathrm{Regret}_{L} \triangleq & \max_{\pi \in \Pi}\mathbb{E}\Bigg[ \sum_{l = 1}^{L} (\frac{1}{\Bar{K}}\sum_{k = (l - 1) \times \Bar{K} + 1}^{l \times \Bar{K}}F^*_k(\mathcal{F}_l) \nonumber\\
        & - \frac{1}{\Bar{K}}\sum_{k = (l - 1) \times \Bar{K} + 1}^{l \times \Bar{K}}F^*_k(\bm{\pi}(\bm{X}_l)) \Bigg], 
    \end{align} 
    $\bm{\pi}(\bm{X}_l) = [\pi(1 \vert \bm{X}_l), \ldots, \pi(|\mathcal{F}| \vert \bm{X}_l)]$ is the strategy vector given $\bm{X}_l$ \cite{neu_efficient_2020}. 

\label{theorem_regret}
\end{Thm}

\begin{proof}
    Please refer to Appendix~\ref{appendix:theorem_regret} for the proof. 
\end{proof}

Theorem \ref{theorem_regret} shows that Ad2S and Ad2S-NR achieve sub-linear regret (e.g. $o(L)$) performance under both stationary and non-stationary scenarios. Furthermore, approximately $1.3  \times$ additional regret is introduced due to the extended contextual dimensions under non-stationary cases, Fig.~\ref{fig:regret} can be referred as the numerical proof. 
% Also, the regret bound grows with the order of $\mathcal{O}((|\mathcal{F}| \log|\mathcal{F}|)^{\frac{1}{3}})$ corresponding to the total sub-channel budget. 
{\color{black}
\begin{Lem}[Computational complexity for Ad2S and Ad2S-NR]
\label{lem_comp_complexity}
    The overall computational complexity for running both Ad2S and Ad2S-NR at the start of super-frame $l$ follows $\mathcal{O}(|\mathcal{F}| (1 + 4N)^2)$ and $\mathcal{O}\left(|\mathcal{F}| (1 + 8N)^2 + N^3\right)$, respectively. 
\end{Lem}
\begin{proof}
    First, we analyze Ad2S's computational complexity. The policy generation step \ref{step policy generation} in Ad2S has the complexity of $\mathcal{O}(|\mathcal{F}| (1 + 4N))$. The parameter update step \ref{step end} in Ad2S has the complexity of $\mathcal{O}(|\mathcal{F}| (1 + 4N)^2)$. The overall computational complexity of Ad2S is dominated by step \ref{step end} and thus follows $\mathcal{O}(|\mathcal{F}| (1 + 4N)^2)$. 

    Then, we analyze Ad2S-NR's computational complexity. The computational complexity is divided into two parts for ME-KF and refined Ad2S, respectively. 
    \begin{enumerate}
        \item{\bf Complexity for ME-KF. } The prediction stage has the complexity of $\mathcal{O}(N^3)$ dominated by \eqref{prediction_stage_covariance}. The extrapolation and fusion stages also have the complexity of $\mathcal{O}(N^3)$ dominated by the update functions in the fusion stage. Then the overall computational complexity for ME-KF follows $\mathcal{O}(N^3)$. 
        \item{\bf Complexity for refined Ad2S. } Similar to Ad2S's computational complexity, refined Ad2S has the overall complexity of $\mathcal{O}(|\mathcal{F}| (1 + 8N)^2)$. 
    \end{enumerate}
    Then, the overall computational complexity of Ad2S-NR follows $\mathcal{O}\left(|\mathcal{F}| (1 + 8N)^2 + N^3\right)$. 
\end{proof}
Lemma~\ref{lem_comp_complexity} shows that both Ad2S and Ad2S-NR mainly encounter complexity bottlenecks of sub-channel number and user number. However, with coarse-grained slicing chunks \cite{zanzi_laco_2021} ($|\mathcal{F}| \ll N$), Ad2S-NR has the complexity of $\mathcal{O}(N^3)$ and its computational speed is primarily limited by the number of users. 
}

