\section{Proof of Lemma~\ref{lem_dmu_long_term}}
\label{appendix:lem_1}
 As Lyapunov drift theorem is constrained under ergodic i.i.d. stochastic assumptions, we constrict \eqref{constraint average queue length, no URLLC} into super-frame based condition as given by

    \begin{small}
    \vspace{-6mm}
    \begin{align}\label{segment_cons}
        \frac{1}{\Bar{K}}\sum_{k = (l - 1) \times \Bar{K} + 1}^{l \times \Bar{K}} Q_n(k) \leq \left\{ 
        \begin{array}{l l}
          \delta_e, & n \in \mathcal{N}_e,\\
          % \delta_U, & n \in \mathcal{N}_U, \\
          \delta_M, & n \in \mathcal{N}_M, 
        \end{array} \right. 
        \forall l. 
    \end{align} 
    \vspace{-3mm}
    \end{small}

\noindent We already have that 
 % arrival and channel are i.i.d. and ergodic within each super-frame and 
 $\Bar{K}$ is sufficiently large as presented in Section~\ref{system model}.  
 Therefore, we refer the segmented constraint \eqref{segment_cons} as a long-term constraint. By making sure that virtual queue $G_n(k)$ is stable and satisfies $\limsup_{K\to\infty}\frac{1}{K}\sum_{k = 0}^{K - 1}G_n(k) < \infty,\quad n\in \mathcal{N}_e \cup \mathcal{N}_M$, \eqref{segment_cons} can be equivalently addressed as specified in \cite{zhao_resource_2022, neely_mj_stochastic_2010}. To solve the problem of virtual queue stability, the Lyapunov-based DMU method is utilized.

The drift of Lyapunov function is

\begin{small}
\vspace{-3mm}
\begin{eqnarray}
\begin{aligned}
    &\mathbb{E}\left[L(\Gamma(k + 1)) - L(\Gamma(k))|\Gamma(k)\right] \nonumber\\
    = & \frac{\omega_Q}{2}\sum_{n\in\mathcal{N}_e \cup \mathcal{N}_M}({G_n(k + 1)}^2 - {G_n(k)}^2). \nonumber
\end{aligned}
\end{eqnarray}
\end{small}


To conserve bandwidth and power resources, $r_n(k)$ is guaranteed to be less than queue length $Q_n(k)$. Therefore, (\ref{dynamic queue model}) can be rewritten as: $Q_{n}(k+1) = Q_{n}(k) - r_n(k) + \Lambda_n(k)$. 

Based on the definition of virtual queue, we can derive

\begin{small}\vspace{-3mm}
    \begin{align}
        &{G_n(k + 1)}^2 - {G_n(k)}^2\nonumber\\
        &={\max\{G_n(k) + Q_n(k + 1) - \delta_{e,M}, 0\}}^2 - {G_n(k)}^2\nonumber\\
        &\leq[G_n(k) + Q_n(k + 1) - \delta_{e,M}]^2 - {G_n(k)}^2\nonumber\\
        &= {(Q_n(k + 1) - \delta_{e,M})}^2 + 2 G_n(k) (Q_n(k + 1) - \delta_{e,M})\nonumber\\
        &= {(Q_n(k) - \eta r_n(k) + \Lambda_n(k))}^2 + {\delta_{e,M}}^2 - 2 Q_n(k + 1) \delta_{e,M} \nonumber\\
        &+ 2 G_n(k) (Q_n(k + 1) - \delta_{e,M})\nonumber\\
        &\leq {(Q_n(k) + \Lambda_n(k))}^2 + {\delta_{e,M}}^2 + 2 G_n(k) Q_n(k) \nonumber\\
        &- 2 G_n(k) \eta r_n(k) + 2 G_n(k) \Lambda_n(k). 
    \label{drift_inequality}
    \end{align}
    \vspace{-3mm}
\end{small}

\noindent
Therefore the expectation of the Lyapunov drift with the status given at last frame can be derived as:

\begin{small}
   \begin{align}
        &\mathbb{E}\left\{{G_n(k + 1)}^2 - {G_n(k)}^2 \vert \Gamma(k)\right\} \leq C_n(k) - 2G_n(k) \eta r_n(k), \nonumber
    \end{align} 
\end{small}

% $C_n = {Q_n(k)}^2 + {\Lambda_n(k)}^2 + 2 Q_n(k)\Lambda_n(k) + {\delta_{e,M}}^2+ 2G_n(k)[Q_n(k) + \Lambda_n(k)]$
\noindent $C_n(k) = {(Q_n(k) + \Lambda_n(k))}^2 + {\delta_{e,M}}^2 + 2 G_n(k) Q_n(k) + 2 G_n(k) \Lambda_n(k)$. Therefore, we have

\begin{small}
\vspace{-3mm}
    \begin{align}
        &\Delta(\Gamma(k)) - \omega_{T}\mathbb{E}\left[ \sum_{n\in\mathcal{N}_e \cup \mathcal{N}_M} r_n(k)|\Gamma(k) \right] \nonumber\\
            &\leq\mathbb{E}\left\{ \frac{\omega_Q}{2} \sum_{n\in\mathcal{N}_{e} \cup \mathcal{N}_M}\left[C_n(k) 
            - 2G_n(k) \eta r_n(k)\right] |\Gamma(k)\right\} \nonumber\\
            &- \omega_{T}\mathbb{E}\left[ \sum_{n\in\mathcal{N}_{e} \cup \mathcal{N}_U \cup \mathcal{N}_M} r_n(k)|\Gamma(k) \right]. \nonumber
    \end{align}
\vspace{-3mm}
\end{small}
\noindent
% Then, we complete the proof of Lemma~\ref{lem_dmu_long_term}. 

